export const PALETTE={wood:{top:'#547b3b',side:'#344b2c'},brick:{top:'#bf7850',side:'#804c30'},sheep:{top:'#a0b955',side:'#667a38'},wheat:{top:'#d6b655',side:'#977934'},ore:{top:'#929995',side:'#5a676a'},desert:{top:'#d8bb7c',side:'#9e7d43'}};
// Board illustrations are original geometry, not imported game assets.
function pine(x,y,k=1){return `<g transform="translate(${x} ${y}) scale(${k})"><ellipse cx="2" cy="12" rx="14" ry="5" fill="#526f4c" opacity=".14"/><path d="M-2 1H2V14H-2Z" fill="#6b4d2e"/><path d="M0-27 15 3H-15Z" fill="#285331"/><path d="M0-27 0 3H-15Z" fill="#416b35"/><path d="M0-17 17 12H-17Z" fill="#1d432c"/><path d="M0-17 0 12H-17Z" fill="#346039"/></g>`;}
function peak(x,y,k=1){return `<g transform="translate(${x} ${y}) scale(${k})"><ellipse cy="11" rx="28" ry="6" fill="#6b8279" opacity=".15"/><path d="M0-32 30 13H-28Z" fill="#52626a"/><path d="M0-32 6 13H-28Z" fill="#78888a"/><path d="m0-32 11 16-10-3-8 6-4-2Z" fill="#dce1d9"/><path d="m0-32 1 13-8 6-4-2Z" fill="#eeeee0"/></g>`;}
function hill(x,y,k=1){return `<g transform="translate(${x} ${y}) scale(${k})"><path d="m-27 11 8-23L-1-24 20-10 30 12Z" fill="#944b30"/><path d="m-27 11 8-23L-1-24 2 9Z" fill="#bb7147"/><path d="m-1-24 21 14-18 19Z" fill="#ab5d39"/><path d="m-15-4 5-8 7 4-1 6Z" fill="#d78d5d" opacity=".8"/><path d="m10 1 7-5 5 9-9 1Z" fill="#7f402c"/></g>`;}
function tuft(x,y,k=1){return `<g transform="translate(${x} ${y}) scale(${k})"><path d="M0 13V-14M-6 11V-7M6 11V-8" stroke="#92712f" stroke-width="1.5"/><g fill="#f4d172"><ellipse cx="-3" cy="-13" rx="2.4" ry="5.3" transform="rotate(-35 -3 -13)"/><ellipse cx="3" cy="-10" rx="2.4" ry="5.3" transform="rotate(35 3 -10)"/><ellipse cx="-3" cy="-5" rx="2.4" ry="5.3" transform="rotate(-35 -3 -5)"/><ellipse cx="3" cy="-2" rx="2.4" ry="5.3" transform="rotate(35 3 -2)"/><ellipse cx="-8" cy="-6" rx="2" ry="4" transform="rotate(-30 -8 -6)"/><ellipse cx="8" cy="-7" rx="2" ry="4" transform="rotate(30 8 -7)"/></g></g>`;}
function sheep(x,y,k=1){return `<g transform="translate(${x} ${y}) scale(${k})"><ellipse cy="8" rx="14" ry="4" fill="#667e35" opacity=".2"/><path d="M-7 0V9M4 0V9" stroke="#8a8e6e" stroke-width="2.5"/><ellipse cx="-2" cy="-2" rx="12" ry="8" fill="#f6eccc"/><circle cx="-8" cy="-6" r="4.5" fill="#fff5da"/><circle cx="-1" cy="-8" r="4.5" fill="#fff5da"/><circle cx="5" cy="-5" r="4.5" fill="#fff5da"/><ellipse cx="10" cy="-2" rx="4" ry="5" fill="#685e42"/><circle cx="11" cy="-3" r=".9" fill="#f7f6e8"/></g>`;}
export function terrainArt(type){
  if(type==='wood')return `<path d="M-44 8Q-28-18-11-19T38 2L29 17H-22Z" fill="#6c8740" opacity=".45"/>`+pine(-28,-4,.78)+pine(-10,-20,.86)+pine(15,-20,.93)+pine(31,0,.67)+pine(0,1,.95);
  if(type==='ore')return peak(-20,-5,.75)+peak(8,-16,1)+peak(28,7,.55);
  if(type==='brick')return hill(-19,-7,.76)+hill(10,-17,.86)+hill(19,9,.6)+`<path d="m-24 5 9-4 8 4-9 5Z" fill="#d69a62" stroke="#8f4d31" stroke-width="1"/><path d="m-24 5 8 5v7l-8-4Z" fill="#995332"/><path d="m-16 10 9-5v7l-9 5Z" fill="#b36a40"/>`;
  if(type==='wheat')return `<path d="m-39 5 28-27m-21 30 30-31m-21 33 30-31m-19 33 27-28" stroke="#ae893b" stroke-width="3" opacity=".35"/>`+`<path d="m-40 8 15-28 40-8 25 25-26 17Z" fill="#d0b466" opacity=".35"/>`+tuft(-21,-5,.9)+tuft(0,-17,1)+tuft(22,-9,.85)+tuft(1,4,.8);
  if(type==='sheep')return `<path d="M-43 2Q-25-25 0-14T43 5Q14 22-22 14Z" fill="#7f9d3f" opacity=".45"/>`+sheep(-19,-4,.87)+sheep(17,-18,.76)+sheep(15,7,.8)+`<path d="m-32 13 2-6 2 6m53-9 2-7 2 7" fill="none" stroke="#67883a" stroke-width="1.5"/>`;
  return `<path d="M-43 9Q-15-19 14 4T44 9L26 16H-20Z" fill="#bc985c"/><path d="M-33-7Q-11-28 18-8Q-1-12-15 1Z" fill="#ead099"/><path d="M22-22V0M16-15V-7H22M28-20V-10H22" stroke="#6d7d3d" stroke-width="4" stroke-linecap="round"/>`;
}
export function pieceArt(type,color='#bd7042'){
 if(type==='road')return `<g transform="rotate(-28)"><path d="M-17-3H17V6H-17Z" fill="${color}" stroke="#fff9e6" stroke-width="1.3"/><path d="M-17 2H17V6H-17Z" fill="#29392d" opacity=".18"/></g>`;
 if(type==='city')return `<path d="M-15 8V-5L-6-13 3-5V-1L10-7 19 0V10L3 15Z" fill="${color}" stroke="#fff8e4" stroke-width="1.4" stroke-linejoin="round"/><path d="M3-5V15L19 10V0L10-7 3-1" fill="#26372c" opacity=".16"/><path d="m-15-5 9-8 9 8-9 5Z" fill="#fff" opacity=".22"/><path d="M-8 7V1H-3V9Z" fill="#fff7df" opacity=".8"/>`;
 return `<path d="m-12-4 12-11 12 11V11L0 17-12 10Z" fill="${color}" stroke="#fff8e4" stroke-width="1.5" stroke-linejoin="round"/><path d="M0 2 12-4V11L0 17Z" fill="#26372c" opacity=".18"/><path d="m-12-4 12-11 12 11L0 2Z" fill="#fff" opacity=".24"/><path d="M-7 7V1L-3 3V9Z" fill="#fff7df" opacity=".85"/>`;
}
export const miniPiece=(type,color)=>`<svg class="build-art" viewBox="-25 -20 50 44" aria-hidden="true">${pieceArt(type,color)}</svg>`;
export function artIcon(type){return `<svg class="resource-art" viewBox="-53 -48 106 96" aria-hidden="true">${terrainArt(type)}</svg>`;}
